    public bool RemoveItem(Item item, int count = 1)
    {
        if (inventory.ContainsKey(item))
        {
            if (inventory[item] >= count)
            {
                inventory[item] -= count;
                if (inventory[item] <= 0)
                {
                    inventory.Remove(item);
                }
                return true;
            }
        }
        Debug.LogWarning("物品不足，无法移除");
        return false;
    }

